<script setup>
import {ref,reactive,computed,onMounted} from 'vue';
import {request,json,query} from './api';
const tab=ref('Обзор'),stations=ref([]),report=ref(null),rows=ref([]),total=ref(0),page=ref(1),busy=ref(false),error=ref(''),notice=ref('');
const filters=reactive({from:'2026-10-15',to:'2026-10-28',region:'',stationId:''});
const applied=ref({...filters});
const station=reactive({id:0,code:'',region:'',technology:'4G'});
const observation=reactive({id:0,stationId:'',date:'2026-10-29',trafficGb:0,calls:0,droppedCalls:0,downtimeMinutes:0});
const regions=computed(()=>[...new Set(stations.value.map(x=>x.region))].sort());
const maxTraffic=computed(()=>Math.max(1,...(report.value?.daily||[]).map(x=>x.trafficGb)));
const num=(v,d=0)=>Number(v||0).toLocaleString('ru-RU',{maximumFractionDigits:d});
async function run(fn){busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function load(){const q=query(applied.value);const [s,r,o]=await Promise.all([request('stations'),request('report?'+q),request(`observations?${q}&page=${page.value}&pageSize=20`)]);stations.value=s;report.value=r;rows.value=o.items;total.value=o.total;}
async function apply(){await run(async()=>{applied.value={...filters};page.value=1;await load();});}
async function move(delta){await run(async()=>{page.value+=delta;await load();});}
function resetStation(){Object.assign(station,{id:0,code:'',region:'',technology:'4G'});}
function resetObservation(){Object.assign(observation,{id:0,stationId:'',date:'2026-10-29',trafficGb:0,calls:0,droppedCalls:0,downtimeMinutes:0});}
async function saveStation(){await run(async()=>{await request('stations'+(station.id?'/'+station.id:''),json(station.id?'PUT':'POST',station));resetStation();await load();notice.value='Станция сохранена';});}
async function saveObservation(){await run(async()=>{await request('observations'+(observation.id?'/'+observation.id:''),json(observation.id?'PUT':'POST',{...observation,stationId:Number(observation.stationId)}));resetObservation();await load();notice.value='Показатели сохранены. При необходимости измените период фильтра.';});}
async function remove(kind,id){if(!confirm('Удалить запись? Это действие нельзя отменить.'))return;await run(async()=>{await request(kind+'/'+id,{method:'DELETE'});page.value=1;await load();notice.value='Запись удалена';});}
async function importCsv(event){const file=event.target.files[0];if(!file)return;await run(async()=>{if(file.size>1048576)throw Error('Максимум 1 МБ');const result=await request('import',{method:'POST',headers:{'Content-Type':'text/csv'},body:await file.text()});await load();notice.value=`Загружено строк: ${result.imported}. Проверьте период фильтра.`;});event.target.value='';}
function template(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['stationCode,date,trafficGb,calls,droppedCalls,downtimeMinutes\nBS-001,2026-10-29,250.5,1200,9,5\n'],{type:'text/csv'}));a.download='template.csv';a.click();URL.revokeObjectURL(a.href);}
function print(){tab.value='Обзор';setTimeout(()=>window.print(),100);}
onMounted(()=>run(load));
</script>
<template>
  <div class="layout">
    <aside><div class="brand"><span class="brandmark">◒</span> Контур связи</div><div class="eyebrow">ОТЧЁТНОСТЬ СЕТИ</div><nav aria-label="Разделы"><button v-for="(name,i) in ['Обзор','Показатели','Станции','Импорт и экспорт']" :key="name" :aria-label="name" :class="{active:tab===name}" @click="tab=name"><span>{{['◫','▤','⌁','⇅'][i]}}</span>{{name}}</button></nav><div class="aside-bottom"><b>Хакатон · кейс 02</b><p>Адаптируемый прототип</p><span class="pill">Демонстрационные данные</span></div></aside>
    <main>
      <header><div><div class="eyebrow">РАБОЧЕЕ ПРОСТРАНСТВО / {{tab.toUpperCase()}}</div><h1>{{tab==='Обзор'?'Сеть в цифрах':tab}}</h1><p>Показатели сотовой сети, собранные в одном месте.</p></div><button class="secondary" @click="run(load)" :disabled="busy">↻ Обновить</button></header>
      <div class="demo-note">Демо-модель: 6 станций, 14 дней. Показатели и формулы уточняются по ТЗ соревнования.</div>
      <p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message success" role="status">{{notice}}</p><p v-if="busy" role="status">Загрузка…</p>
      <form class="filters card" @submit.prevent="apply"><label>С даты<input aria-label="С даты" type="date" v-model="filters.from"></label><label>По дату<input aria-label="По дату" type="date" v-model="filters.to"></label><label>Регион<select v-model="filters.region"><option value="">Все регионы</option><option v-for="r in regions" :key="r">{{r}}</option></select></label><label>Станция<select v-model="filters.stationId"><option value="">Все станции</option><option v-for="s in stations" :key="s.id" :value="s.id">{{s.code}}</option></select></label><button :disabled="busy">Применить</button></form>
      <template v-if="tab==='Обзор' && report">
        <section class="metrics"><article class="card"><span>Трафик данных</span><strong>{{num(report.trafficGb,1)}} <small>ГБ</small></strong><p>{{num(report.records)}} суточных записей</p></article><article class="card"><span>Доступность по записям</span><strong>{{num(report.availability,3)}}<small>%</small></strong><p>Простой: {{num(report.downtimeMinutes)}} мин</p></article><article class="card"><span>Доля обрывов</span><strong>{{num(report.dropRate,3)}}<small>%</small></strong><p>{{num(report.calls)}} вызовов всего</p></article><article class="card"><span>Станций в отчёте</span><strong>{{report.stations}}</strong><p>С данными за выбранный период</p></article></section>
        <section class="card chart"><div class="section-head"><div><h2>Динамика трафика</h2><p>Суммарный объём по дням · ГБ</p></div><span class="pill">{{report.daily.length}} дней</span></div><div v-if="report.daily.length" class="bars" role="img" aria-label="Динамика трафика по дням"><div v-for="d in report.daily" :key="d.date" class="bar-col" :title="`${d.date}: ${num(d.trafficGb)} ГБ`"><span class="bar-value">{{num(d.trafficGb)}}</span><div class="bar" :style="{height:(d.trafficGb/maxTraffic*150+2)+'px'}"></div><small>{{d.date.slice(8)}}</small></div></div><p v-else class="empty">За выбранный период нет данных.</p></section>
        <section class="card"><div class="section-head"><div><h2>Сводка по регионам</h2><p>Доступность рассчитана только по загруженным станция-дням</p></div><button class="secondary" @click="tab='Показатели'">Все показатели →</button></div><div class="table-scroll"><table><thead><tr><th>Регион</th><th>Записей</th><th>Трафик, ГБ</th><th>Доступность</th></tr></thead><tbody><tr v-for="r in report.regions" :key="r.region"><td><b>{{r.region}}</b></td><td>{{r.records}}</td><td>{{num(r.trafficGb)}}</td><td><span :class="['badge',r.availability<99?'warning':'good']">{{num(r.availability,3)}}%</span></td></tr></tbody></table></div><p v-if="!report.regions.length" class="empty">Нет данных</p></section>
      </template>
      <template v-if="tab==='Станции'">
        <form class="card editor" @submit.prevent="saveStation"><h2>{{station.id?'Редактирование':'Новая станция'}}</h2><label>Код<input required maxlength="40" pattern="[A-Za-z0-9_-]+" v-model="station.code" placeholder="BS-007"></label><label>Регион<input required maxlength="80" v-model="station.region" placeholder="Восток"></label><label>Технология<select v-model="station.technology"><option v-for="t in ['2G','3G','4G','5G']" :key="t">{{t}}</option></select></label><button :disabled="busy">Сохранить станцию</button><button type="button" class="secondary" @click="resetStation">Очистить</button></form>
        <section class="card table-scroll"><table><thead><tr><th>Код</th><th>Регион</th><th>Технология</th><th>Действия</th></tr></thead><tbody><tr v-for="s in stations" :key="s.id"><td><b>{{s.code}}</b></td><td>{{s.region}}</td><td>{{s.technology}}</td><td><button class="text" @click="Object.assign(station,s)">Изменить</button><button class="text danger" @click="remove('stations',s.id)" :disabled="busy">Удалить</button></td></tr></tbody></table></section>
      </template>
      <template v-if="tab==='Показатели'">
        <form class="card editor" @submit.prevent="saveObservation"><h2>{{observation.id?'Редактирование записи':'Новая суточная запись'}}</h2><label>Станция<select required v-model="observation.stationId"><option value="" disabled>Выберите</option><option v-for="s in stations" :key="s.id" :value="s.id">{{s.code}}</option></select></label><label>Дата<input required type="date" v-model="observation.date"></label><label>Трафик, ГБ<input required type="number" min="0" max="1000000000" step="any" v-model.number="observation.trafficGb"></label><label>Вызовов<input required type="number" min="0" max="2147483647" v-model.number="observation.calls"></label><label>Обрывов<input required type="number" min="0" :max="observation.calls" v-model.number="observation.droppedCalls"></label><label>Простой, мин<input required type="number" min="0" max="1440" v-model.number="observation.downtimeMinutes"></label><button :disabled="busy">Сохранить показатели</button><button type="button" class="secondary" @click="resetObservation">Очистить</button></form>
        <section class="card"><div class="section-head"><h2>Суточные показатели <span class="muted">{{total}}</span></h2><a class="button secondary" :href="'/api/export?'+query(applied)">Скачать CSV</a></div><div class="table-scroll"><table><thead><tr><th>Дата</th><th>Станция</th><th>ГБ</th><th>Вызовы</th><th>Обрывы</th><th>Простой, мин</th><th>Действия</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.date}}</td><td>{{r.stationCode}}</td><td>{{num(r.trafficGb,2)}}</td><td>{{num(r.calls)}}</td><td>{{r.droppedCalls}}</td><td>{{r.downtimeMinutes}}</td><td><button class="text" @click="Object.assign(observation,r)">Изменить</button><button class="text danger" @click="remove('observations',r.id)" :disabled="busy">Удалить</button></td></tr></tbody></table></div><p v-if="!rows.length" class="empty">Нет данных. Измените фильтр или добавьте запись.</p><div class="pagination"><button class="secondary" :disabled="page===1 || busy" @click="move(-1)">← Назад</button><span>{{page}} / {{Math.max(1,Math.ceil(total/20))}}</span><button class="secondary" :disabled="page*20>=total || busy" @click="move(1)">Вперёд →</button></div></section>
      </template>
      <section v-if="tab==='Импорт и экспорт'" class="card transfer"><h2>Данные без ручного переноса</h2><p>CSV в UTF-8, разделитель — запятая, десятичная точка. Одна строка на станцию за сутки. Сначала создайте станции.</p><pre>stationCode,date,trafficGb,calls,droppedCalls,downtimeMinutes
BS-001,2026-10-29,250.5,1200,9,5</pre><p>Не более 1 МБ и 5000 строк. Ошибки и повторы отменяют весь импорт. Существующие записи не перезаписываются.</p><div class="actions"><button class="secondary" @click="template">Скачать шаблон</button><label class="button">Загрузить CSV<input class="file" type="file" accept=".csv,text/csv" :disabled="busy" @change="importCsv"></label><a class="button secondary" :href="'/api/export?'+query(applied)">Экспорт по фильтру</a><button class="secondary" @click="print()">Печать отчёта</button></div><p>Для печати откройте «Обзор» и используйте печать браузера (Ctrl+P).</p></section>
      <footer>Контур связи · MVP 0.1 <span>Демонстрационный стенд без авторизации · только синтетические данные</span></footer>
    </main>
  </div>
</template>